package bo.asistencia.offline;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.graphics.pdf.PdfDocument;import android.widget.*;import android.view.*;import org.json.*;import java.text.*;import java.util.*;import java.io.*;
public class MainActivity extends Activity {
 LinearLayout root; EditText name,role,start,end,vortex,dest,tripFrom,tripTo; TextView info; Spinner month; EditText year; JSONObject db; String today(){return new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date());} String now(){return new SimpleDateFormat("HH:mm",Locale.US).format(new Date());}
 void save(){getPreferences(0).edit().putString("data",db.toString()).apply();}
 String get(String key){return db.optString(key,"");} void put(String key,String val){try{db.put(key,val);save();}catch(Exception e){}}
 EditText field(String title,String value){TextView t=new TextView(this);t.setText(title);t.setTextSize(14);root.addView(t);EditText e=new EditText(this);e.setSingleLine(true);e.setText(value);root.addView(e);return e;}
 void button(String title,Runnable run){Button b=new Button(this);b.setText(title);root.addView(b);b.setOnClickListener(v->run.run());}
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 JSONObject marks(){JSONObject x=db.optJSONObject("marks");if(x==null){x=new JSONObject();try{db.put("marks",x);}catch(Exception e){}}return x;}
 JSONArray trips(){JSONArray x=db.optJSONArray("trips");if(x==null){x=new JSONArray();try{db.put("trips",x);}catch(Exception e){}}return x;}
 void mark(String type){String date=today();if(!get("start").isEmpty()&&date.compareTo(get("start"))<0){toast("Contrato aún no iniciado");return;}if(!get("end").isEmpty()&&date.compareTo(get("end"))>0){toast("Contrato finalizado");return;}try{JSONObject m=marks().optJSONObject(date);if(m==null)m=new JSONObject();m.put(type,now());marks().put(date,m);save();toast("Marcación "+type+": "+now());showHistory();}catch(Exception e){toast(e.toString());}}
 void showHistory(){StringBuilder s=new StringBuilder();JSONObject m=marks();ArrayList<String> dates=new ArrayList<>();Iterator<String> it=m.keys();while(it.hasNext())dates.add(it.next());Collections.sort(dates);for(String d:dates){JSONObject v=m.optJSONObject(d);s.append(d).append("  ").append(v.optString("ingreso","--")).append(" / ").append(v.optString("salida","--")).append("\n");}info.setText(s.length()==0?"Sin marcaciones todavía":s.toString());}
 void pdf(){try{int y=Integer.parseInt(year.getText().toString()),mo=month.getSelectedItemPosition();PdfDocument doc=new PdfDocument();PdfDocument.PageInfo pi=new PdfDocument.PageInfo.Builder(842,1191,1).create();PdfDocument.Page page=doc.startPage(pi);Canvas c=page.getCanvas();Paint p=new Paint(3);p.setColor(Color.BLACK);p.setTextSize(15);c.drawText("PLANILLA DE SEGUIMIENTO DE ASISTENCIA",80,55,p);p.setTextSize(12);c.drawText("SERVICIO DE CONSULTORIA DE LINEA",80,76,p);c.drawText("CONSULTOR: "+get("name"),40,112,p);c.drawText("CARGO: "+get("role"),40,135,p);c.drawText("MES: "+(mo+1)+"     AÑO: "+y,40,160,p);p.setTextSize(11);c.drawText("FECHA",45,190,p);c.drawText("INGRESO",275,190,p);c.drawText("SALIDA",490,190,p);Calendar cal=Calendar.getInstance();cal.set(y,mo,1);int count=cal.getActualMaximum(Calendar.DAY_OF_MONTH),yy=215;JSONObject marks=marks();for(int d=1;d<=count;d++){cal.set(Calendar.DAY_OF_MONTH,d);int dow=cal.get(Calendar.DAY_OF_WEEK);if(dow==1||dow==7)continue;String date=String.format(Locale.US,"%04d-%02d-%02d",y,mo+1,d);JSONObject m=marks.optJSONObject(date);c.drawText(date,45,yy,p);c.drawText(m==null?"--":m.optString("ingreso","--"),275,yy,p);c.drawText(m==null?"--":m.optString("salida","--"),490,yy,p);yy+=22;}yy+=20;c.drawText("VIAJES DE COMISION",45,yy,p);yy+=22;JSONArray tr=trips();for(int i=0;i<tr.length()&&yy<1030;i++){JSONObject t=tr.optJSONObject(i);c.drawText(t.optString("vortex")+"  "+t.optString("dest")+"  "+t.optString("from")+" a "+t.optString("to"),45,yy,p);yy+=20;}c.drawText("Elaborado por: CONSULTOR",45,1120,p);c.drawText("Revisado por: CONTRAPARTE",430,1120,p);doc.finishPage(page);File dir=getExternalFilesDir(android.os.Environment.DIRECTORY_DOCUMENTS);if(dir==null)dir=getFilesDir();File f=new File(dir,"Asistencia_"+y+"_"+(mo+1)+".pdf");try(FileOutputStream out=new FileOutputStream(f)){doc.writeTo(out);}doc.close();new AlertDialog.Builder(this).setTitle("PDF generado").setMessage("Guardado en "+f.getAbsolutePath()+"\n\nEste informe es provisional y aún no conserva los logotipos ni el diseño exacto de la plantilla original.").setPositiveButton("OK",null).show();}catch(Exception e){toast("Error PDF: "+e);}}
 public void onCreate(Bundle b){super.onCreate(b);try{db=new JSONObject(getPreferences(0).getString("data","{}"));}catch(Exception e){db=new JSONObject();}ScrollView scroll=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(28,24,28,30);scroll.addView(root);setContentView(scroll);TextView title=new TextView(this);title.setText("MI ASISTENCIA · SIN INTERNET");title.setTextSize(22);root.addView(title);name=field("Nombre completo",get("name"));role=field("Cargo",get("role"));start=field("Inicio contrato (AAAA-MM-DD)",get("start"));end=field("Fin contrato (opcional)",get("end"));button("Guardar perfil",()->{put("name",name.getText().toString());put("role",role.getText().toString());put("start",start.getText().toString());put("end",end.getText().toString());toast("Perfil guardado");});TextView schedule=new TextView(this);schedule.setText("Horario de referencia: lunes a viernes, 08:00 - 17:00");root.addView(schedule);button("MARCAR INGRESO",()->mark("ingreso"));button("MARCAR SALIDA",()->mark("salida"));info=new TextView(this);root.addView(info);showHistory();TextView travel=new TextView(this);travel.setText("VIAJES DE COMISIÓN");travel.setTextSize(19);root.addView(travel);vortex=field("Número VORTEX","");dest=field("Destino","");tripFrom=field("Desde (AAAA-MM-DD)","");tripTo=field("Hasta (AAAA-MM-DD)","");button("Guardar viaje",()->{try{JSONObject t=new JSONObject();t.put("vortex",vortex.getText().toString());t.put("dest",dest.getText().toString());t.put("from",tripFrom.getText().toString());t.put("to",tripTo.getText().toString());trips().put(t);save();toast("Viaje guardado");}catch(Exception e){toast(e.toString());}});TextView reports=new TextView(this);reports.setText("INFORME MENSUAL");reports.setTextSize(19);root.addView(reports);month=new Spinner(this);String[] months={"Enero","Febrero","Marzo","Abril","Mayo","Junio","Julio","Agosto","Septiembre","Octubre","Noviembre","Diciembre"};month.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,months));month.setSelection(Calendar.getInstance().get(Calendar.MONTH));root.addView(month);year=field("Año",String.valueOf(Calendar.getInstance().get(Calendar.YEAR)));button("Generar PDF provisional",()->pdf());}
}